INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(124331, 'ruRU', '', 'В общем, продолжаем!', 24330),
(124332, 'ruRU', '', 'Следующий отвод должен быть здесь.', 24330),
(124336, 'ruRU', '', 'Прими нашу благодарность. Мы будем внимательно следить за их численностью.', 24330),
(124337, 'ruRU', '', 'Странные хищники вторгаются в эту экосистему. Сократи их численность, прежде чем они распространятся!', 24330),
(124338, 'ruRU', '', 'Ещё одна победа! Ты показал себя настоящим охотником на зверей.', 24330),
(124339, 'ruRU', '', 'Их крылья подрезаны.', 24330),
(124340, 'ruRU', '', 'Ты отлично справился с устранением этой пернатой угрозы.', 24330),
(124341, 'ruRU', '', 'Мы слышали много крика! Надеемся, это значит, что ты победил.', 24330),
(124342, 'ruRU', '', 'Хищные птицы прилетели с моря. Отбрось их обратно в море, иначе нас захлестнёт.', 24330),
(124343, 'ruRU', '', 'Эти пернатые бесы размножаются неконтролируемо! Положи конец их какофоническому пиршеству!', 24330),
(124344, 'ruRU', '', 'Берегись острых когтей этих птичьих зверей! Мы нашли их весьма свирепыми.', 24330),
(124345, 'ruRU', '', 'Ещё больше буйных птиц захватили эту территорию. Сократи их численность, прежде чем эти яйца вылупятся.', 24330),
(124351, 'ruRU', '', 'Потренируйся использовать свои атаки, уничтожая эти тренировочные манекены.', 24330),
(124359, 'ruRU', '', 'Интересует покупка чего-то... закулисного?', 24330),
(124363, 'ruRU', '', 'Внимание, бойцы! $n заключил сделку с целителями душ! Можете умирать сколько угодно!', 24330),
(124374, 'ruRU', '', 'Можешь помочь мне найти лей-линии, если это необходимо. Только постарайся не мешать мне.', 24330),
(124401, 'ruRU', '', 'Ты смотришь эти бои? На этом ринге раздаётся немало тумаков. Кажется, в меня угодило чьим-то зубом.', 24330),
(124403, 'ruRU', '', 'Чувствуешь себя везучим? $n хочет, чтобы ты поговорил с хозяином арены Баксдоглом и проверил свой... потенциал заработка золота.', 24330),
(124405, 'ruRU', '', 'Я воспользуюсь телепортом до поместья и приведу наших самых сильных иссохших. Встретимся там.', 24330),
(124406, 'ruRU', '', '$n сдал достаточно золота, чтобы обойти правила арены. Поговори с рядовым, если хочешь сразиться со случайным бойцом!', 24330),
(124418, 'ruRU', '', 'Уютно, уединённо и кишит тайной энергией. Возможно, мне нужно построить здесь мастерскую...', 24330),
(124419, 'ruRU', '', 'Эта пещера действительно хорошо скрыта. Я удивлён, что Окулету удалось доставить нас сюда целыми.', 24330),
(124420, 'ruRU', '', 'Готов начать ритуал, $n?', 24330),
(124426, 'ruRU', '', 'Элизанда сделала ТЕБЯ Первым Чародеем? Выбор, должно быть, был действительно скудным. Отпусти Ли''лет немедленно!', 24330),
(124427, 'ruRU', '', 'Ха! Это всё, что ты привёл? Чужак и стая безмозглых, изголодавшихся по мане трупов? Да, у тебя действительно настали трудные времена.', 24330),
(124428, 'ruRU', '', 'Я покажу тебе, на что способны эти трупы. В атаку!', 24330),
(124429, 'ruRU', '', 'Бедная Талисра... ты так старательно пытаешься спасти свой народ, но отрезаешь его от единственного, что может его восстановить! Боюсь, Ли''лет заплатит цену за твою гордыню.', 24330),
(124430, 'ruRU', '', 'Испытаем же стойкость твоего восстания! Пошли лучших сразиться со мной в поместье Ли''лет... прежде чем я приведу ещё горожан для... допроса!', 24330),
(124431, 'ruRU', '', 'Как будто я стану утруждать себя личной встречей с тобой. Демонорождённые! Убейте их!', 24330),
(124432, 'ruRU', '', 'Иссохшие... побеждены так легко демонической магией. Прошу... спаси тех, кого можешь. Мои раны... не важны!', 24330),
(124441, 'ruRU', '', 'Что бы ты ни планировал сделать, делай это быстро. Я чувствую приближение чего-то... голодного!', 24330),
(124442, 'ruRU', '', 'Осторожно, защитник! Оно здесь!', 24330),
(124448, 'ruRU', '', 'Мне нужно отдохнуть, прежде чем мы отправимся обратно в Шал''Аран. Это было более утомительно, чем я ожидал...', 24330),
(124449, 'ruRU', '', 'Из тебя вышел отличный помощник. Твои врождённые знания о лей-линиях почти так же обширны, как мои.', 24330),
(124450, 'ruRU', '', 'Я знаю, на что она способна. Именно поэтому мы должны остановить её.', 24330),
(124451, 'ruRU', '', 'Иди вперёд и сообщи Талисре. У меня есть несколько вопросов для нашего друга здесь.', 24330),
(124452, 'ruRU', '', 'Ты и впрямь визуализируешь линии, или это больше похоже на то, что ты их ощущаешь? Это постоянное ощущение, или ты можешь включать и выключать его?', 24330),
(124454, 'ruRU', '', 'Твой контроль над такими обширными энергиями впечатляет. Это была непростая задача.', 24330),
(124455, 'ruRU', '', 'Дрогбары устраивают хаос на Громовом Тотеме, разбрасывая наши барабаны и разгоняя наш скот. Эти беспорядки нужно прекратить!', 24330),
(124456, 'ruRU', '', 'Порядок восстановлен. Твоя помощь здесь всегда желанна, защитник. За Крутогорье!', 24330);
